+            } else if (m1IsContract) {
+                return -1; // mission1 comes before mission2
+            } else if (m2IsContract) {
+                return 1; // mission1 comes after mission2
+            } else {
+                return 0; // both are non-Contract, maintain relative order
+            }
+        });
