+                factionStandings.updateClimateRegard(campaignFaction, today);
+                reports.addAll(factionStandings.updateCampaignForPastMissions(missions,
+                      campaignIcon,
+                      campaignFaction,
+                      today));
+            } else {
+                reports.add(getTextAt(RESOURCE_BUNDLE, "gmTools.ZERO_ALL_REGARD.report"));
+                factionStandings.resetAllFactionStandings();
+                factionStandings.setClimateRegard(new HashMap<>());
+            }
+            dispose();
+        });
+
+        pnlButtons.add(btnCancel);
+        pnlButtons.add(Box.createRigidArea(new Dimension(10, 0)));
+        pnlButtons.add(btnConfirm);
+
+        return pnlButtons;
+    }
+
+    /**
+     * Handles actions to perform when a hyperlink event occurs in the dialog, such as glossary lookups.
+     *
+     * @param evt the {@link HyperlinkEvent} that was received.
+     *
+     * @author Illiani
+     * @since 0.50.07
+     */
+    protected void hyperlinkEventListenerActions(HyperlinkEvent evt) {
+        if (evt.getEventType() == HyperlinkEvent.EventType.ACTIVATED) {
+            handleImmersiveHyperlinkClick(evt.getDescription());
+        }
+    }
+
+    /**
+     * Processes logic when immersive (in-dialog) hyperlinks are clicked.
+     *
+     * @param reference the string reference associated with the hyperlink.
+     *
+     * @author Illiani
+     * @since 0.50.07
+     */
+    private void handleImmersiveHyperlinkClick(String reference) {
+        String[] splitReference = reference.split(":");
+
+        String commandKey = splitReference[0];
+        String entryKey = splitReference[1];
+
+        if (commandKey.equalsIgnoreCase(GLOSSARY_COMMAND_STRING)) {
+            new GlossaryDialog(this, entryKey);
+        } else {
+            LOGGER.warn("Invalid hyperlink command: {}", commandKey);
+        }
+    }
+}

